<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  body{margin:0;font-family:sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center;}
  #controls{margin:10px;}
  button{margin:0 5px;padding:8px 12px;background:#333;border:none;color:white;cursor:pointer;}
  button:hover{background:#555;}
  canvas{border:1px solid #444;background:#222;}
</style>
</head>
<body>
<div id="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
</div>
<canvas id="life" width="400" height="400"></canvas>

<script>
(function(){
  const canvas=document.getElementById('life');
  const ctx=canvas.getContext('2d');
  const w=40, h=40; // grid dimensions
  const cellSize=10;
  let grid=new Uint8Array(w*h);
  let anim=null;

  function index(x,y){ return y*w+x; }
  window.life={w,h,
    get:(x,y)=>{ if(x<0||x>=w||y<0||y>=h)return 0; return grid[index(x,y)]; },
    set:(x,y,v)=>{ if(x<0||x>=w||y<0||y>=h)return; grid[index(x,y)] = v?1:0; draw(); },
    step:step,
    clear:clear
  };

  function draw(){
    ctx.clearRect(0,0,w*cellSize,h*cellSize);
    ctx.fillStyle='#00ff00';
    for(let y=0;y<h;y++){
      for(let x=0;x<w;x++){
        if(grid[index(x,y)]){
          ctx.fillRect(x*cellSize,y*cellSize,cellSize-1,cellSize-1);
        }
      }
    }
  }

  function step(){
    const next=new Uint8Array(w*h);
    for(let y=0;y<h;y++){
      for(let x=0;x<w;x++){
        let alive=grid[index(x,y)];
        let neigh=
          window.life.get(x-1,y-1)+window.life.get(x,y-1)+window.life.get(x+1,y-1)+
          window.life.get(x-1,y  )                      +window.life.get(x+1,y  )+
          window.life.get(x-1,y+1)+window.life.get(x,y+1)+window.life.get(x+1,y+1);
        if(alive){
          next[index(x,y)]= (neigh===2||neigh===3)?1:0;
        }else{
          next[index(x,y)]=(neigh===3)?1:0;
        }
      }
    }
    grid=next;
    draw();
  }

  function clear(){
    grid=new Uint8Array(w*h);
    draw();
  }

  function random(){
    for(let i=0;i<w*h;i++) grid[i]=Math.random()<0.2?1:0;
    draw();
  }

  document.getElementById('step').addEventListener('click',step);
  document.getElementById('clear').addEventListener('click',clear);
  document.getElementById('random').addEventListener('click',random);
  const playBtn=document.getElementById('play');
  playBtn.addEventListener('click',()=>{
    if(anim){ clearInterval(anim); anim=null; playBtn.textContent='Play'; }
    else{ anim=setInterval(step,200); playBtn.textContent='Pause'; }
  });

  // painting
  let drawing=false;
  canvas.addEventListener('mousedown',(e)=>{drawing=true;toggleCell(e)});
  canvas.addEventListener('mousemove',(e)=>{if(drawing) toggleCell(e)});
  canvas.addEventListener('mouseup',()=>drawing=false);
  canvas.addEventListener('mouseleave',()=>drawing=false);

  function toggleCell(evt){
    const rect=canvas.getBoundingClientRect();
    const x=Math.floor((evt.clientX-rect.left)/cellSize);
    const y=Math.floor((evt.clientY-rect.top)/cellSize);
    if(x>=0&&x<w&&y>=0&&y<h){
      const idx=index(x,y);
      grid[idx]=grid[idx]?0:1;
      draw();
    }
  }

  // initial draw
  draw();
})();
</script>
</body>
</html>
